_cache = {}
TTL = 300   # seconds

def rate(cur):
    hit = _cache.get(cur)   # key = the currency
    if hit and time.monotonic() - hit[0] < TTL:
        return hit[1]
    value = requests.get(f"https://api.example.com/rate/{cur}").json()["rate"]
    _cache[cur] = (time.monotonic(), value)
    return value
# invalidation: expires after TTL, or _cache.pop(cur) on a known change

